using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "ShadowMasteryCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Moonie/ShadowMasteryCustomDescription", order = 0)]
public class ShadowMasteryCustomDescription : CustomBattleActionDescription
{
	private const string gainAdditionalEffectForEachID = "GainAdditionalEffectForEach";

	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		ShadowMasteryAction shadowMasteryAction = battleAction as ShadowMasteryAction;
		string actionDescription = shadowMasteryAction.PlayerSelfDoomAction.GetActionDescription(1);
		string rawLocalizedDescription = GetRawLocalizedDescription(battleAction);
		string text = Smart.Format(base.localizationManager.GetLocalizedString("GainAdditionalEffectForEach"), GetFinalAmountWithoutEquation(amountModified), shadowMasteryAction.PlayerSelfDoomAction.Effect.GetEffectName(), Smart.Format(base.localizationManager.GetLocalizedInYourHand(removeDotIfJapaneseOrTraditionalChinese: true), rawLocalizedDescription));
		string arg = shadowMasteryAction.PurifyAction.GetActionDescription(shadowMasteryAction.Multiplier).RemoveLast();
		string localizedForEach = base.localizationManager.GetLocalizedForEach();
		return actionDescription + "\n" + text + "\n" + Smart.Format(localizedForEach, arg, Smart.Format(base.localizationManager.GetLocalizedInYourHand(removeDotIfJapaneseOrTraditionalChinese: true), rawLocalizedDescription)).AddDotIfJapaneseOrKoreanOrTraditionalChinese();
	}
}
